<?php
namespace App\Filament\Resources\CourseEquivalencys;
use App\Models\CourseEquivalency; use App\Filament\Resources\CourseEquivalencys\Pages; use Filament\Forms\Components\{Select,Textarea}; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Support\Icons\Heroicon; use Filament\Tables\{Actions\DeleteAction,Actions\EditAction,Columns\TextColumn,Table}; use BackedEnum; use UnitEnum;
class CourseEquivalencyResource extends Resource { protected static ?string $slug = 'course-equivalencies'; protected static ?string $model=CourseEquivalency::class; protected static string|BackedEnum|null $navigationIcon=Heroicon::OutlinedArrowsRightLeft; protected static string|UnitEnum|null $navigationGroup='Kurikulum & Mata Kuliah'; protected static ?string $navigationLabel='Ekuivalensi Mata Kuliah'; protected static ?string $modelLabel='Ekuivalensi Mata Kuliah'; protected static ?string $pluralModelLabel='Ekuivalensi Mata Kuliah'; public static function form(Schema $schema):Schema{return $schema->components([Select::make('student_id')->label('Mahasiswa')->relationship('student','nim')->searchable()->preload()->required(),Select::make('original_course_id')->label('Mata Kuliah Asal')->relationship('originalCourse','name')->searchable()->preload()->required(),Select::make('equivalent_course_id')->label('Mata Kuliah Pengganti')->relationship('equivalentCourse','name')->searchable()->preload()->required()->different('original_course_id'),Textarea::make('reason')->label('Alasan')->required()->columnSpanFull()]);} public static function table(Table $table):Table{return $table->columns([TextColumn::make('student.nim')->label('NIM')->searchable(),TextColumn::make('originalCourse.code')->label('Kode Asal'),TextColumn::make('originalCourse.name')->label('Mata Kuliah Asal'),TextColumn::make('equivalentCourse.code')->label('Kode Pengganti'),TextColumn::make('approved_at')->label('Disetujui Pada')->dateTime('d M Y H:i')->placeholder('Belum disetujui')])->actions([EditAction::make()->label('Ubah'),DeleteAction::make()->label('Hapus')->requiresConfirmation()]);} public static function getPages():array{return ['index'=>Pages\ListCourseEquivalencys::route('/'),'create'=>Pages\CreateCourseEquivalency::route('/create'),'edit'=>Pages\EditCourseEquivalency::route('/{record}/edit')];}}
